    max_k = 40
    f = [[0] * (max_c + 1) for _ in range(max_k + 1)]

    # f[k][c] = max moves to get 2^k with max cells c
    # At k=0, 2^0 can be obtained in 1 move (type 1)
    for c in range(1, max_c + 1):
        f[0][c] = 1

    for k in range(1, max_k + 1):
        for c in range(1, max_c + 1):
            if c == 1:
                f[k][c] = 1
            else:
                # To get 2^k with max cells c:
                # We could get 2^{k-1} in f[k-1][c] moves.
                # Then we could get another 2^{k-1} in f[k-1][c-1] moves.
                # Then combine them in 1 move.
                f[k][c] = f[k-1][c] + f[k-1][c-1] + 1

    return f[max_k][max_c]

